<?php
function handle_infrastructure_action(string $action): bool {
    switch($action){
        case 'infrastructure_automation_save':require_admin();save_infrastructure_automation($_POST);flash('Automatik-Einstellungen gespeichert. Der OVH-Abgleich ist vorgemerkt.');redirect('/admin/infrastruktur?bereich=automatik');
        case 'template_runner_download':require_admin();download_template_runner();
        case 'template_build_queue':require_admin();$id=(int)($_POST['id']??0);$job=queue_template_build($id);flash('Vorlage zur automatischen Erstellung vorgemerkt (Auftrag #'.$job.').');redirect('/admin/infrastruktur?bereich=vorlagen&id='.$id);
        case 'template_build_clear':require_admin();clear_template_build((int)($_POST['build_id']??0));flash('Entfernter Baucontainer bestätigt, Bau-IP wieder für den Vorlagendienst verfügbar.');redirect('/admin/infrastruktur?bereich=automatik');
        case 'infrastructure_settings':require_admin();save_infrastructure_settings($_POST);flash('Netzwerk- und Webserver-Vorgaben gespeichert.');redirect('/admin/infrastruktur');
        case 'order_network_assign':require_admin();$id=(int)($_POST['order_id']??0);assign_order_network($id,(int)($_POST['address_id']??0));flash('Feste IP für diese Bestellung reserviert.');redirect('/admin/bestellungen?id='.$id);
        case 'server_operation_retry':require_admin();$id=(int)($_POST['operation_id']??0);$o=one('SELECT * FROM shop_server_operations WHERE id=?',[$id]);if(!$o || $o['state']!=='needs_action' || !in_array($o['phase'],['start','stop_wait','delete_wait','restore_wait','ready'],true))throw new RuntimeException('Dieser Auftrag benötigt eine persönliche Prüfung des Anbieterzustands.');query("UPDATE shop_server_operations SET state='waiting',last_error=NULL WHERE id=? AND locked_until<?",[$id,time()]);flash('Serverauftrag zur Fortsetzung vorgemerkt.');redirect('/admin/infrastruktur?bereich=vorlagen');
        case 'network_save':require_admin();$id=save_network_address((int)($_POST['id']??0),$_POST);flash('IP-/MAC-Zuordnung gespeichert.');redirect('/admin/infrastruktur?bereich=ips&id='.$id);
        case 'network_ovh_import':require_admin();rate_limit('network_ovh_import',5,3600);if(!run_ovh_inventory_sync(true))throw new RuntimeException('Der Abgleich läuft bereits oder OVH ist noch nicht verbunden.');$r=one("SELECT * FROM shop_infrastructure_sync WHERE provider='ovh'");$counts=json_decode($r['summary'],true);flash($counts['created'].' Adressen importiert, '.$counts['updated'].' Zuordnungen aktualisiert. '.($r['last_error']?:'Neue Adressen bitte prüfen und einzeln freigeben.'));redirect('/admin/infrastruktur?bereich=ips');
        case 'server_template_save':require_admin();$id=save_server_template((int)($_POST['id']??0),$_POST);if(!isset($_POST['active']) && infrastructure_automation_settings()['auto_build_saved']){queue_template_build($id);flash('Vorlage gespeichert und automatische Erstellung vorgemerkt.');}else flash('LXC-Vorlage gespeichert.');redirect('/admin/infrastruktur?bereich=vorlagen&id='.$id);
        case 'server_template_seed':require_admin();$node=integration_row('proxmox')?integration_config('proxmox',false)['node']:'';foreach(['debian'=>'Debian','ubuntu'=>'Ubuntu','postgresql'=>'PostgreSQL','dolibarr'=>'Dolibarr','apache-tomcat'=>'Apache Tomcat','caddy'=>'Caddy','n8n'=>'n8n','nextcloudpi'=>'NextCloudPi','centos'=>'CentOS','fedora'=>'Fedora','gentoo'=>'Gentoo','archlinux'=>'Arch Linux'] as $slug=>$name){$url='https://community-scripts.org/scripts/'.$slug;if(one('SELECT id FROM shop_server_templates WHERE source_url=?',[$url]))continue;query("INSERT INTO shop_server_templates (name,description,node,archive,storage,source_url,settings) VALUES (?,?,?,'','local-lvm',?,?)",[$name,'Vorbereiteten Container als LXC-Backup auf Proxmox hinterlegen. Anschließend Volume und Ressourcen prüfen.',$node,$url,json_encode(['unprivileged'=>1,'nesting'=>in_array($slug,['n8n','nextcloudpi'],true)?1:0,'keyctl'=>0,'disk_gb'=>8,'min_memory_mb'=>512,'min_cores'=>1,'nameserver'=>'1.1.1.1'])]);}flash('Community-Script-Vorlagen als Entwürfe angelegt. Bitte die vorbereiteten Proxmox-Volumes zuordnen.');redirect('/admin/infrastruktur?bereich=vorlagen');
        case 'server_archives_read':require_admin();rate_limit('server_archives',20,900);$node=trim((string)($_POST['node']??''));if(!preg_match('/^[\w.-]{1,80}$/D',$node))throw new RuntimeException('Bitte einen gültigen Node auswählen.');$api=new ProxmoxProvider();$volumes=[];foreach($api->call('GET','/nodes/'.rawurlencode($node).'/storage') as $storage){if(empty($storage['active']))continue;foreach($api->call('GET','/nodes/'.rawurlencode($node).'/storage/'.rawurlencode($storage['storage']).'/content') as $v)if(in_array($v['content']??'',['vztmpl','backup'],true) && (str_contains($v['volid']??'',':vztmpl/') || str_contains($v['volid']??'','vzdump-lxc-')))$volumes[]=['volid'=>$v['volid'],'size'=>$v['size']??0];}$GLOBALS['server_archive_options']=$volumes;$GLOBALS['server_archive_node']=$node;return true;
        case 'dns_template_save':require_admin();save_dns_template($_POST);flash('DNS-Vorlage gespeichert. Neue bezahlte Domainbestellungen verwenden die freigegebene Vorlage.');redirect('/admin/infrastruktur?bereich=dns');
        case 'dns_job_retry':require_admin();$id=(int)($_POST['order_id']??0);query("UPDATE shop_dns_jobs SET state='pending',last_error=NULL WHERE order_id=? AND state='needs_action' AND locked_until<?",[$id,time()]);flash('DNS-Auftrag zur erneuten Prüfung vorgemerkt.');redirect('/admin/infrastruktur?bereich=dns');
        case 'module_intent_create':$u=require_user();rate_limit('module_buy',20,3600);$s=bound_service((int)($_POST['service_id']??0),(int)$u['id'],true);$i=module_create_intent($s,(int)($_POST['module_id']??0),$_POST['quantity']??0,(string)($_POST['purchase_key']??''));redirect('/konto/zusatzmodul?id='.$i['id']);
        case 'module_checkout':$u=require_user();rate_limit('module_checkout',15,3600);$o=start_module_checkout($u,(int)($_POST['intent_id']??0),(string)($_POST['checkout_key']??''),$_POST);if($o['payment_kind']==='no_charge')redirect('/konto/bestellungen?id='.$o['id']);approval_redirect($o['approval_url']);
        case 'module_intent_remove':$u=require_user();$i=one('SELECT * FROM shop_module_intents WHERE id=? AND customer_id=?',[(int)($_POST['intent_id']??0),$u['id']]);if(!$i || $i['order_id'] || $i['state']!=='selected')throw new RuntimeException('Ein bereits bestelltes Modul bitte über seinen Vertrag kündigen.');if(zero_base_initial_parent($i))throw new RuntimeException('Bitte für eine andere Erstausstattung die gesamte unbezahlte Bestellung kündigen und neu konfigurieren.');query("UPDATE shop_module_intents SET state='ended' WHERE id=?",[$i['id']]);flash('Unbezahlte Modulauswahl entfernt.');redirect('/konto/bestellungen?id='.$i['parent_order_id']);
        case 'server_reinstall':$u=require_user();rate_limit('server_reinstall',3,3600);$s=bound_service((int)($_POST['service_id']??0),(int)$u['id'],true);request_server_reinstall($s,(int)($_POST['server_template']??0),(string)($_POST['confirmation']??''),(string)($_POST['operation_key']??''));flash('Die bestätigte Neuinstallation wurde vorgemerkt. Die Server-IP bleibt erhalten. Neue Zugangsdaten folgen per E-Mail.');redirect('/konto/verwalten?id='.$s['id']);
        default:return false;
    }
}
